"""Split one S3 object into chunk objects, at line boundaries or by bytes (ADR 0110).

The source is read as a stream and never held whole. Each chunk is written
to destination_prefix, under the folder of the step attempt that splits it:
<RUN_ID>/<STEP_ID>/<ATTEMPT>/chunk-000000, numbered from 0. A resumed attempt
writes the same keys with the same bytes; a retried attempt writes a folder
of its own. Outside a workflow step there is no attempt, so the tool refuses.

In lines mode each chunk ends just after a newline, or at the end of the
source, and holds at most chunk_bytes bytes. A line longer than that is
refused rather than cut. Finding the boundaries takes one read of the source
and writing the chunks a second, so a source that needs more than
max_chunks chunks, or holds a line too long, is refused before anything is
written. In bytes mode every chunk but the last holds exactly chunk_bytes.

Both reads, and the size the boundaries come from, are pinned to the
version the tool first saw: its version ID in a versioned bucket, its ETag
in any other. A source changed while it is split is refused.

The tool reaches S3 with boto3 and the AWS credentials it is given. Every
problem with its inputs exits with status 2, and every other failure with
status 1; errors are written as UTF-8, whatever the platform's encoding.
"""

import json
import os
import sys

LINEAGE_VARIABLE = "AZATHOTH_LINEAGE"
S3_PREFIX = "s3://"
MODES = ("lines", "bytes")
DEFAULT_MODE = "lines"
DEFAULT_CHUNK_BYTES = 5 * 1024 * 1024
MAX_CHUNK_BYTES = 100 * 1024 * 1024
READ_BYTES = 1024 * 1024
CHANGED_CODES = ("PreconditionFailed", "412")
MISSING_BOTO3 = "split_s3_object needs boto3, which is not installed; install azathoth-ai[worker]."


class Failure(Exception):
    """A failure to report on stderr, with the status to exit with."""

    def __init__(self, status, message):
        super().__init__(message)
        self.status = status
        self.message = message


def sentence(text):
    """Return text ending with exactly one period."""

    return text.rstrip().rstrip(".") + "."


def is_whole(value):
    """Return whether a JSON value is an integer, and not a boolean."""

    return isinstance(value, int) and not isinstance(value, bool)


def parse_s3_uri(value):
    """Return (bucket, path) of an s3:// URI, or None when it is not one."""

    if not isinstance(value, str) or not value.startswith(S3_PREFIX):
        return None

    bucket, _, path = value[len(S3_PREFIX) :].partition("/")

    if not bucket:
        return None

    return bucket, path


def attempt_folder(lineage):
    """Return <RUN_ID>/<STEP_ID>/<ATTEMPT>/ of the step attempt a lineage names."""

    refused = Failure(
        2,
        "split_s3_object writes chunks only from a workflow step, and was not run in one.",
    )

    if not lineage:
        raise refused

    try:
        step = json.loads(lineage)["step"]
        return f"{step['run_id']}/{step['step_id']}/{step['attempt']}/"
    except (ValueError, KeyError, TypeError) as exc:
        raise refused from exc


def parse(inputs, lineage):
    """Return the plan of one split from the tool's inputs and its step's lineage."""

    if not isinstance(inputs, dict) or not isinstance(inputs.get("settings"), dict):
        raise Failure(2, "split_s3_object needs 'settings' to be an object.")

    settings = inputs["settings"]
    source = parse_s3_uri(inputs.get("uri"))

    if source is None or not source[1]:
        raise Failure(2, "split_s3_object needs 'uri' to be an s3:// URI naming an object.")

    destination = parse_s3_uri(settings.get("destination_prefix"))

    if destination is None:
        raise Failure(
            2,
            "split_s3_object needs 'destination_prefix' to be an s3:// URI naming a bucket.",
        )

    mode = settings.get("mode", DEFAULT_MODE)
    chunk_bytes = settings.get("chunk_bytes", DEFAULT_CHUNK_BYTES)
    max_chunks = settings.get("max_chunks")

    if mode not in MODES:
        raise Failure(2, "split_s3_object needs 'mode' to be 'lines' or 'bytes'.")

    if not is_whole(chunk_bytes) or not 1 <= chunk_bytes <= MAX_CHUNK_BYTES:
        raise Failure(
            2,
            f"split_s3_object needs 'chunk_bytes' to be a whole number from 1 to "
            f"{MAX_CHUNK_BYTES}.",
        )

    if not is_whole(max_chunks) or max_chunks < 1:
        raise Failure(2, "split_s3_object needs 'max_chunks' to be a whole number of at least 1.")

    prefix = destination[1]

    if prefix and not prefix.endswith("/"):
        prefix += "/"

    return {
        "uri": inputs["uri"],
        "bucket": source[0],
        "key": source[1],
        "destination_bucket": destination[0],
        "destination_prefix": prefix + attempt_folder(lineage),
        "mode": mode,
        "chunk_bytes": chunk_bytes,
        "max_chunks": max_chunks,
    }


def open_client():
    """Return an S3 client, from boto3 and the credentials the tool was given."""

    try:
        import boto3
    except ImportError as exc:
        raise Failure(1, MISSING_BOTO3) from exc

    return boto3.client("s3")


def call(verb, uri, operation, *, pinned=False, **parameters):
    """Make one S3 call, reporting its failure as the tool's own.

    A pinned read that S3 refuses for its precondition read a source that
    changed since the tool first saw it.
    """

    from botocore.exceptions import BotoCoreError, ClientError

    try:
        return operation(**parameters)
    except ClientError as exc:
        error = exc.response.get("Error", {})
        code = error.get("Code", "Unknown")

        if pinned and code in CHANGED_CODES:
            raise changed(uri) from exc

        raise Failure(
            1,
            sentence(f"split_s3_object could not {verb} {uri}: {code}: {error.get('Message', '')}"),
        ) from exc
    except BotoCoreError as exc:
        raise Failure(1, sentence(f"split_s3_object could not {verb} {uri}: {exc}")) from exc


def changed(uri):
    """Return the failure of a source that changed while it was split."""

    return Failure(1, f"split_s3_object found {uri} changed while splitting it.")


def stream(client, plan, source, read_bytes):
    """Yield the source's bytes, pinned to the version first seen, in pieces."""

    from botocore.exceptions import BotoCoreError

    response = call(
        "read",
        plan["uri"],
        client.get_object,
        pinned=True,
        Bucket=plan["bucket"],
        Key=plan["key"],
        **source["pin"],
    )

    try:
        yield from response["Body"].iter_chunks(read_bytes)
    except (BotoCoreError, OSError) as exc:
        raise Failure(1, sentence(f"split_s3_object could not read {plan['uri']}: {exc}")) from exc


def too_many_lines(plan):
    """Return the failure of a source that needs more than max_chunks chunks of lines."""

    return Failure(
        1,
        f"split_s3_object would split {plan['uri']} into more than its max_chunks of "
        f"{plan['max_chunks']} chunks.",
    )


def line_ends(client, plan, source, read_bytes):
    """Return where each chunk of lines ends, reading the source once."""

    chunk_bytes = plan["chunk_bytes"]
    size = source["size_bytes"]

    if -(-size // chunk_bytes) > plan["max_chunks"]:
        raise too_many_lines(plan)

    if not size:
        return []

    ends = []
    start = 0
    last_break = None
    base = 0

    for piece in stream(client, plan, source, read_bytes):
        index = 0

        while True:
            limit = start + chunk_bytes

            if base + len(piece) <= limit:
                newline = piece.rfind(b"\n", index)

                if newline != -1:
                    last_break = base + newline + 1

                break

            newline = piece.rfind(b"\n", index, limit - base)

            if newline != -1:
                last_break = base + newline + 1

            if last_break is None:
                raise Failure(
                    1,
                    f"split_s3_object found a line at byte {start} of {plan['uri']} "
                    f"longer than its chunk_bytes of {chunk_bytes}.",
                )

            ends.append(last_break)

            if len(ends) >= plan["max_chunks"]:
                raise too_many_lines(plan)

            start = last_break
            last_break = None
            index = max(start - base, 0)

        base += len(piece)

    if base != size:
        raise changed(plan["uri"])

    if base > start:
        ends.append(base)

    return ends


def byte_ends(plan, source):
    """Return where each chunk of exactly chunk_bytes bytes ends, the last excepted."""

    chunk_bytes = plan["chunk_bytes"]
    size = source["size_bytes"]
    ends = [*range(chunk_bytes, size, chunk_bytes), size] if size else []

    if len(ends) > plan["max_chunks"]:
        raise Failure(
            1,
            f"split_s3_object would split {plan['uri']} into {len(ends)} chunks, "
            f"more than its max_chunks of {plan['max_chunks']}.",
        )

    return ends


def write_chunks(client, plan, source, ends, read_bytes):
    """Read the source again and write each chunk as it fills; return the chunks."""

    chunks = []

    if not ends:
        return chunks

    buffer = bytearray()
    offset = 0

    for piece in stream(client, plan, source, read_bytes):
        buffer += piece

        while len(chunks) < len(ends) and offset + len(buffer) >= ends[len(chunks)]:
            end = ends[len(chunks)]
            content = bytes(buffer[: end - offset])
            del buffer[: end - offset]
            offset = end
            chunks.append(write_chunk(client, plan, source, len(chunks), content))

    if len(chunks) != len(ends) or buffer:
        raise changed(plan["uri"])

    return chunks


def write_chunk(client, plan, source, index, content):
    """Write one chunk object; return its entry in the tool's output."""

    key = f"{plan['destination_prefix']}chunk-{index:06d}"
    uri = f"{S3_PREFIX}{plan['destination_bucket']}/{key}"
    parameters = {"Bucket": plan["destination_bucket"], "Key": key, "Body": content}

    if source["content_type"]:
        parameters["ContentType"] = source["content_type"]

    call("write", uri, client.put_object, **parameters)

    return {"uri": uri, "index": index, "size_bytes": len(content)}


def split(client, plan, *, read_bytes=READ_BYTES):
    """Split the source a plan names into chunk objects; return the tool's output."""

    head = call("read", plan["uri"], client.head_object, Bucket=plan["bucket"], Key=plan["key"])
    version_id = head.get("VersionId")
    source = {
        "size_bytes": head["ContentLength"],
        "content_type": head.get("ContentType"),
        "pin": {"VersionId": version_id} if version_id else {"IfMatch": head["ETag"]},
    }

    if plan["mode"] == "lines":
        ends = line_ends(client, plan, source, read_bytes)
    else:
        ends = byte_ends(plan, source)

    chunks = write_chunks(client, plan, source, ends, read_bytes)

    return {
        "chunks": chunks,
        "count": len(chunks),
        "source": {
            "uri": plan["uri"],
            "etag": head["ETag"].strip('"'),
            "version_id": version_id,
            "size_bytes": source["size_bytes"],
        },
    }


def main():
    """Split the object the tool's inputs name, and print its chunks."""

    try:
        plan = parse(json.load(sys.stdin), os.environ.get(LINEAGE_VARIABLE))
        output = split(open_client(), plan)
    except Failure as failure:
        sys.stderr.buffer.write(failure.message.encode("utf-8"))
        sys.stderr.flush()
        sys.exit(failure.status)

    json.dump(output, sys.stdout)


if __name__ == "__main__":
    main()
